SourceCode.Declaration:
/// <summary>
/// Generic hook for business event telemetry.
/// BusinessEventsBase.send() is Wrappable(false) and
/// BusinessEventsPublisher.publishOnUserConnection() is Hookable(false),
/// so the single commit log insert point is used instead.
/// </summary>
internal final class METBusinessEventsCommitLogEventHandler
{
}

Method.Source:
/// <summary>
/// Logs each business event written to the commit log.
/// </summary>
/// <param name = "_sender">The inserted BusinessEventsCommitLog record.</param>
/// <param name = "_e">Data event arguments.</param>
[DataEventHandler(tableStr(BusinessEventsCommitLog), DataEventType::Inserted)]
public static void BusinessEventsCommitLog_onInserted(Common _sender, DataEventArgs _e)
{
    BusinessEventsCommitLog commitLog = _sender as BusinessEventsCommitLog;

    METBusinessEventTelemetryHelper::logBusinessEventTriggered(commitLog);
}
